import React, { useState } from 'react';
import {
  Alert,
  Box,
  Button,
  Chip,
  CircularProgress,
  Stack,
  Typography,
} from '@mui/material';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import ApiService from '../../services/api';
import { queryKeys } from '../../constants/queryKeys';
import useAppTranslation from '../../hooks/useAppTranslation';

type DraftSuggestion = {
  id: string;
  label: string;
  scope: string;
  detail?: string | null;
};

const DRAFT_FIELD_LABELS: Record<string, string> = {
  'CSRD:emissions.reportingPeriod': 'Reporting period',
};

const draftSuggestionFieldName = (label: string): string => {
  const match = label.match(/^(Export pack field:\s*)(.+)$/i);
  const prefix = match ? match[1] : '';
  const path = (match ? match[2] : label).trim();
  const known = DRAFT_FIELD_LABELS[path];
  if (known) return `${prefix}${known}`;
  if (!path.includes(':') && !path.includes('.')) return label;
  const leaf = path.split(/[:.]/).filter(Boolean).pop() || path;
  const words = leaf
    .replace(/[_-]+/g, ' ')
    .replace(/([a-z])([A-Z])/g, '$1 $2')
    .trim();
  if (!words) return label;
  return `${prefix}${words.charAt(0).toUpperCase()}${words.slice(1)}`;
};

const DraftReadinessConfirmationBanner: React.FC = () => {
  const { t } = useAppTranslation();
  const queryClient = useQueryClient();
  const [actingScope, setActingScope] = useState<string | 'all' | null>(null);
  const [actingMode, setActingMode] = useState<'confirm' | 'reject' | null>(null);
  const [feedback, setFeedback] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  const suggestionsQuery = useQuery({
    queryKey: queryKeys.platform.draftSuggestions,
    queryFn: async () => {
      const response = await ApiService.getDraftReadinessSuggestions();
      return ((response as { data?: DraftSuggestion[] })?.data || []) as DraftSuggestion[];
    },
    staleTime: 60 * 1000,
  });

  const suggestions = suggestionsQuery.data || [];

  const invalidateCaches = async () => {
    await queryClient.invalidateQueries({ queryKey: queryKeys.platform.draftSuggestions });
    await queryClient.invalidateQueries({ queryKey: ['reporting', 'readiness-overview'] });
    await queryClient.invalidateQueries({ queryKey: queryKeys.reporting.all });
  };

  const handleConfirm = async (scopes?: string[]) => {
    const token = scopes?.length === 1 ? scopes[0] : 'all';
    setActingScope(token);
    setActingMode('confirm');
    setError(null);
    setFeedback(null);
    try {
      const response = await ApiService.confirmDraftReadinessSuggestions(scopes);
      const confirmed = (response as { data?: { confirmed?: string[] } })?.data?.confirmed || [];
      await invalidateCaches();
      setFeedback(
        confirmed.length
          ? t('reporting.draftConfirmed').replace('{count}', String(confirmed.length))
          : t('reporting.draftNoneNeeded')
      );
    } catch (e) {
      setError(e instanceof Error ? e.message : t('reporting.draftConfirmFailed'));
    } finally {
      setActingScope(null);
      setActingMode(null);
    }
  };

  const handleReject = async (scopes?: string[]) => {
    const token = scopes?.length === 1 ? scopes[0] : 'all';
    setActingScope(token);
    setActingMode('reject');
    setError(null);
    setFeedback(null);
    try {
      const response = await ApiService.rejectDraftReadinessSuggestions(scopes);
      const rejected = (response as { data?: { rejected?: string[] } })?.data?.rejected || [];
      await invalidateCaches();
      setFeedback(
        rejected.length
          ? t('reporting.draftRejected').replace('{count}', String(rejected.length))
          : t('reporting.draftNoneNeeded')
      );
    } catch (e) {
      setError(e instanceof Error ? e.message : t('reporting.draftRejectFailed'));
    } finally {
      setActingScope(null);
      setActingMode(null);
    }
  };

  if (suggestionsQuery.isLoading || suggestions.length === 0) {
    return null;
  }

  return (
    <Alert severity="info" sx={{ mb: 2 }}>
      <Stack spacing={1.5}>
        <Box>
          <Typography variant="subtitle2" fontWeight={700}>
            {t('reporting.reviewAutopilot')}
          </Typography>
          <Typography variant="body2">
            {t('reporting.reviewAutopilotDetail')}
          </Typography>
        </Box>
        <Stack spacing={1}>
          {suggestions.map((item: DraftSuggestion) => {
            const fieldName = draftSuggestionFieldName(item.label);
            return (
            <Stack key={item.id} direction="row" spacing={1} alignItems="center" flexWrap="wrap" useFlexGap>
              <Chip
                size="small"
                label={fieldName}
                title={fieldName === item.label ? undefined : item.label}
                variant="outlined"
              />
              <Button
                variant="outlined"
                size="small"
                disabled={actingScope !== null}
                onClick={() => void handleConfirm([item.scope])}
                startIcon={actingScope === item.scope && actingMode === 'confirm' ? <CircularProgress size={14} /> : undefined}
              >
                {t('common.confirmOne')}
              </Button>
              <Button
                variant="text"
                size="small"
                color="inherit"
                disabled={actingScope !== null}
                onClick={() => void handleReject([item.scope])}
                startIcon={actingScope === item.scope && actingMode === 'reject' ? <CircularProgress size={14} /> : undefined}
              >
                {t('common.dismissOne')}
              </Button>
            </Stack>
            );
          })}
        </Stack>
        {feedback ? <Typography variant="body2">{feedback}</Typography> : null}
        {error ? <Typography variant="body2" color="error">{error}</Typography> : null}
        <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap>
          <Button
            variant="contained"
            size="small"
            disabled={actingScope !== null}
            onClick={() => void handleConfirm()}
            startIcon={actingScope === 'all' && actingMode === 'confirm' ? <CircularProgress size={14} color="inherit" /> : undefined}
          >
            {t('common.confirmAllDraft')}
          </Button>
          <Button
            variant="outlined"
            size="small"
            disabled={actingScope !== null}
            onClick={() => void handleReject()}
            startIcon={actingScope === 'all' && actingMode === 'reject' ? <CircularProgress size={14} /> : undefined}
          >
            {t('common.dismissAllDraft')}
          </Button>
        </Stack>
      </Stack>
    </Alert>
  );
};

export default DraftReadinessConfirmationBanner;
